<!doctype html><html lang="en"><head><meta charset="UTF-8"><title>Recruiter Complaints</title><link rel="stylesheet" href="/project/public/assets/css/style.css"></head><body><div class="container"><h2>Submit Complaint to Admin</h2><?php if (!empty($_GET['success'])): ?><div class="alert alert-success">Complaint submitted.</div><?php endif; ?><?php if (!empty($_GET['error'])): ?><div class="alert alert-error">Provide a valid subject and at least 15 characters description.</div><?php endif; ?><form method="post" action="index.php?route=recruiter/complaints/submit"><label>Subject User (Employer/Seeker)</label><select name="subject_id" required><option value="">Select user</option><?php foreach ($subjects as $s): ?><option value="<?php echo (int)$s['id']; ?>"><?php echo htmlspecialchars($s['name'] . ' (' . $s['role'] . ')'); ?></option><?php endforeach; ?></select><label>Description</label><textarea name="description" required placeholder="Describe the issue"></textarea><div class="actions"><button type="submit">Submit Complaint</button><a class="btn btn-secondary" href="index.php?route=recruiter/dashboard">Back</a></div></form><h3>My Submitted Complaints</h3><div class="table-wrap"><table><tr><th>Subject</th><th>Description</th><th>Status</th><th>Admin Note</th><th>Created</th></tr><?php foreach ($complaints as $c): ?><tr><td><?php echo htmlspecialchars($c['subject_name']); ?></td><td><?php echo nl2br(htmlspecialchars($c['description'])); ?></td><td><?php echo htmlspecialchars($c['status']); ?></td><td><?php echo nl2br(htmlspecialchars($c['admin_note'] ?? '')); ?></td><td><?php echo htmlspecialchars($c['created_at']); ?></td></tr><?php endforeach; ?></table></div></div></body></html>
